do $$
declare
  v_provider uuid; v_country uuid; v_system uuid; v_source uuid; v_profile uuid; v_version uuid; v_cfg jsonb; v_completeness uuid; v_trial uuid; v_course uuid; r record;
begin
  select id into v_provider from catalogue.providers where canonical_name='Federation University Australia' limit 1;
  select id into v_country from ref.countries where iso_alpha2='AU' limit 1;
  if v_provider is null or v_country is null then raise exception 'Federation provider or AU country missing'; end if;
  select id into v_system from integration.systems where code='au_federation_course_pages' limit 1;
  if v_system is null then insert into integration.systems(code,name,system_type,base_url,status,config) values('au_federation_course_pages','Federation University Australia official course pages','provider_website','https://www.federation.edu.au','active',jsonb_build_object('country','AU','authority','first_party_provider','provider_cricos','00103D')) returning id into v_system; end if;
  select id into v_source from pipeline.sources where provider_id=v_provider and source_type='provider_course_page' and label='Federation University Australia official course pages' limit 1;
  if v_source is null then insert into pipeline.sources(source_type,system_id,provider_id,country_id,url,label,trust_rank,status,metadata) values('provider_course_page',v_system,v_provider,v_country,'https://www.federation.edu.au/courses/','Federation University Australia official course pages',95,'active',jsonb_build_object('facts',jsonb_build_array('course_link','international_fee','intake','english_requirement','description'),'course_identity','canonical_title_plus_regulatory_guard','provider_cricos','00103D')) returning id into v_source; end if;
  select id into v_profile from pipeline.layer2_source_profiles where profile_key='au-federation-course-detail';
  if v_profile is null then insert into pipeline.layer2_source_profiles(source_id,profile_key,domain,acquisition_method,target_entity_type,authority_class,enabled,paused,operational_owner,freshness_sla_hours,schedule_text) values(v_source,'au-federation-course-detail','course_facts','course_detail','course_fact','first_party',true,false,'PIM/Data Operations',168,'manual/governed') returning id into v_profile; end if;
  v_cfg:=jsonb_build_object('retry',jsonb_build_object('backoff','exponential','max_attempts',3),'headers',jsonb_build_object('user_agent','CourseFinder deterministic acquisition'),'schedule','manual/governed','pagination',jsonb_build_object('mode','source_specific'),'base_domain','https://www.federation.edu.au','concurrency',2,'url_patterns',jsonb_build_array('https://www.federation.edu.au/courses/','https://www.federation.edu.au/study/'),'discovery_url','https://www.federation.edu.au/study/search/course-by-level/undergraduate/','robots_policy','respect','authentication',jsonb_build_object('mechanism','none_or_server_secret_reference'),'max_payload_mb',25,'parser_profile','deterministic-v1','exclusion_rules','[]'::jsonb,'inclusion_rules','[]'::jsonb,'timeout_seconds',30,'mapping_strategy','stable Layer 1 Course match; exact regulatory code where available; otherwise guarded canonical-title identity','source_authority','official/first-party deterministic enrichment','evidence_required',true,'operational_owner','PIM/Data Operations','acquisition_method','course_detail','allowed_mime_types',jsonb_build_array('text/html','application/json'),'change_control_ref','CF-CHG-20260823-029','discovery_strategy',jsonb_build_object('type','first_party_catalogue_and_course_slug','query_fields',jsonb_build_array('canonical_title','course_code'),'result_scope','course','catalogue_url','https://www.federation.edu.au/study/search/course-by-level/undergraduate/','identity_confirmation',jsonb_build_array('course_code','canonical_title')),'target_entity_type','course_fact','freshness_sla_hours',168,'content_change_policy','hash_then_observe_never_direct_canonical_mutation','rate_limit_per_minute',30,'regulatory_code_extraction',jsonb_build_object('cricos','00103D','nzqa',null),'stable_identifier_strategy','exact_cricos_course_code_else_guarded_title_match');
  select id into v_version from pipeline.layer2_source_profile_versions where profile_id=v_profile and configuration_hash=encode(extensions.digest(convert_to(v_cfg::text,'UTF8'),'sha256'),'hex');
  if v_version is null then insert into pipeline.layer2_source_profile_versions(profile_id,version_no,configuration,configuration_hash,validation_status,validation_result,change_control_ref,uat_ref) values(v_profile,coalesce((select max(version_no)+1 from pipeline.layer2_source_profile_versions where profile_id=v_profile),1),v_cfg,encode(extensions.digest(convert_to(v_cfg::text,'UTF8'),'sha256'),'hex'),'valid',jsonb_build_object('validated_for','bounded M2.1 Federation University trial','canonical_mutation_authorised',false),'CF-CHG-20260823-029','M2.1-FEDERATION-TRIAL-2026-08-24') returning id into v_version; end if;
  update pipeline.layer2_source_profiles set current_version_id=v_version,enabled=true,paused=false,updated_at=now() where id=v_profile;
  for r in select id,provider_key from pipeline.layer2_acquisition_providers where provider_key in ('direct-http','scrape-do','firecrawl','zenrows') loop insert into pipeline.layer2_profile_provider_routes(profile_id,acquisition_provider_id,priority,enabled,required_capabilities,request_overrides,evidence_policy,fallback_on,change_control_ref) values(v_profile,r.id,case r.provider_key when 'direct-http' then 10 when 'scrape-do' then 20 when 'firecrawl' then 40 else 50 end,true,'{}'::jsonb,'{}'::jsonb,'{"capture_raw":true,"capture_html":true,"capture_screenshot_on_failure":true}'::jsonb,'["blocked","timeout","403","429","extraction_failed"]'::jsonb,'CF-CHG-20260823-029') on conflict(profile_id,acquisition_provider_id) do update set priority=excluded.priority,enabled=true,updated_at=now(); end loop;
  insert into pipeline.layer2_execution_policies(profile_id,schedule_mode,batch_size,routing_strategy,max_paid_attempts_per_entity,auto_handoff_layer3,stop_on_identity_mismatch,enabled) values(v_profile,'manual',5,'direct_then_best_value',2,true,true,true) on conflict(profile_id) do update set batch_size=5,routing_strategy='direct_then_best_value',max_paid_attempts_per_entity=2,auto_handoff_layer3=true,stop_on_identity_mismatch=true,enabled=true,updated_at=now();
  select id into v_completeness from pipeline.layer2_country_completeness_profiles where country_id=v_country and active=true order by created_at desc limit 1;
  if v_completeness is null then raise exception 'AU completeness profile not found'; end if;
  select id into v_trial from pipeline.layer2_completeness_trials where provider_id=v_provider and trial_mode='adaptive_provider_batch' and status in ('planned','running') order by created_at desc limit 1;
  if v_trial is null then insert into pipeline.layer2_completeness_trials(country_id,completeness_profile_id,provider_id,trial_mode,requested_batch_size,status,baseline_summary,result_summary,recommendation,change_control_ref,uat_ref,started_at) values(v_country,v_completeness,v_provider,'adaptive_provider_batch',5,'running',jsonb_build_object('batch_size',5,'provider','Federation University Australia','purpose','first bounded M2.1 provider/completeness learning cohort'),'{}'::jsonb,'{}'::jsonb,'CF-CHG-20260823-029','M2.1-FEDERATION-TRIAL-2026-08-24',now()) returning id into v_trial; end if;
  for r in select * from (values (1,'085611C','https://www.federation.edu.au/courses/dhm5-bachelor-of-arts/','distinct current title control'),(2,'116438F','https://www.federation.edu.au/courses/dbu5.acc-bachelor-of-business-accounting','distinct specialised course'),(3,'116471E','https://www.federation.edu.au/courses/dit5.cs-bachelor-of--information-technology-cybersecurity','distinct specialised course'),(4,'119893C','https://www.federation.edu.au/courses/dsi5.env-bachelor-of-science-environmental-science','distinct specialised course'),(5,'088661B','https://www.federation.edu.au/courses/dsi8-bachelor-of-science-honours/','distinct honours course')) as x(sample_rank,course_code,target_url,reason) loop select id into v_course from catalogue.courses where provider_id=v_provider and course_code=r.course_code limit 1; if v_course is null then continue; end if; insert into pipeline.layer2_completeness_trial_courses(trial_id,course_id,provider_id,sample_rank,selection_reason,baseline_factual,baseline_context,status) values(v_trial,v_course,v_provider,r.sample_rank,r.reason||' | target='||r.target_url,pipeline.layer2_course_factual_snapshot(v_course),'{}'::jsonb,'selected') on conflict(trial_id,course_id) do update set sample_rank=excluded.sample_rank,selection_reason=excluded.selection_reason,baseline_factual=excluded.baseline_factual; end loop;
end $$;
